:root {
  --bg: #0b1220;
  --panel: #121b30;
  --line: #22304c;
  --ink: #e8eef9;
  --muted: #8fa0bc;
  --accent: #5cc8ff;
  --farm: #3ddc97;
  --thin: #f5b84c;
  --skip: #f26d6d;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-variant-numeric: tabular-nums;
}
header {
  padding: 16px 24px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--panel);
}
.brand h1 { margin: 0; font-size: 18px; letter-spacing: 0.02em; color: var(--ink); }
.brand .sub { margin: 2px 0 0; color: var(--muted); font-size: 12px; }
nav a {
  color: var(--accent);
  text-decoration: none;
  margin-left: 16px;
  font-weight: 500;
}
nav a:hover { text-decoration: underline; }
main { padding: 20px 24px; max-width: 1400px; margin: 0 auto; }

/* KPIs */
.kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}
.kpi-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 12px 16px;
}
.kpi-card .label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
.kpi-card .value { font-size: 20px; font-weight: 600; color: var(--ink); margin-top: 4px; }

/* Method Strip */
.method-strip {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 10px 16px;
  margin-bottom: 16px;
  color: var(--muted);
  font-size: 12px;
}
.method-strip strong { color: var(--accent); }

/* Filter Bar */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 12px 16px;
  margin-bottom: 16px;
}
.filter-bar select, .filter-bar input[type="text"] {
  background: var(--bg);
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 6px 10px;
  border-radius: 4px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.filter-bar select { min-width: 130px; }
.filter-bar input[type="text"] { flex: 1; min-width: 180px; }
.filter-bar label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
  cursor: pointer;
}
.filter-bar .counter {
  margin-left: auto;
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
}
th, td {
  text-align: left;
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
th {
  color: var(--muted);
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  background: rgba(34, 48, 76, 0.4);
}
th:hover { color: var(--ink); }
tbody tr { height: 36px; cursor: pointer; }
tbody tr:hover { background: rgba(92, 200, 255, 0.05); }
tbody tr:last-child td { border-bottom: none; }

.pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 11px;
  text-align: center;
}
.FARM { background: var(--farm); color: #06231a; }
.THIN { background: var(--thin); color: #2a1d03; }
.SKIP { background: var(--skip); color: #2c0808; }

.watchlist-star { color: #f5b84c; margin-right: 4px; }

/* Range bar visual */
.range-cell { display: flex; flex-direction: column; gap: 2px; }
.range-val { font-weight: 500; }
.range-sub { font-size: 11px; color: var(--muted); }
.range-bar-container {
  position: relative;
  width: 90px;
  height: 4px;
  background: var(--line);
  border-radius: 2px;
  margin-top: 3px;
}
.range-bar-fill {
  position: absolute;
  top: 0;
  height: 100%;
  background: var(--accent);
  border-radius: 2px;
}

/* Detail View */
.detail-view { display: flex; flex-direction: column; gap: 20px; }
.back-link { color: var(--accent); text-decoration: none; display: inline-flex; align-items: center; gap: 6px; font-weight: 500; margin-bottom: 4px; }
.back-link:hover { text-decoration: underline; }
.detail-header {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.detail-title h2 { margin: 0 0 4px; font-size: 20px; color: var(--ink); }
.detail-meta { display: flex; gap: 12px; color: var(--muted); font-size: 12px; flex-wrap: wrap; }
.panel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 900px) { .panel-grid { grid-template-columns: 1fr; } }
.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px 20px;
}
.card h3 { margin: 0 0 12px; font-size: 14px; color: var(--accent); border-bottom: 1px solid var(--line); padding-bottom: 8px; }
.facts-list { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fact-item .f-label { color: var(--muted); font-size: 11px; text-transform: uppercase; }
.fact-item .f-val { font-size: 13px; font-weight: 500; margin-top: 2px; }

/* Farm Steps list */
.farm-steps-list { display: flex; flex-direction: column; gap: 10px; }
.farm-step-item {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 10px 12px;
}
.farm-step-num { font-weight: 600; color: var(--accent); font-size: 11px; margin-bottom: 2px; }
.farm-step-text { font-size: 12px; color: var(--ink); }
.farm-step-chips { display: flex; gap: 8px; margin-top: 6px; font-size: 11px; }
.chip { background: rgba(34, 48, 76, 0.8); border: 1px solid var(--line); padding: 1px 6px; border-radius: 3px; color: var(--muted); }

/* Arithmetic grid */
.arithmetic-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 16px; }
.arith-item { display: flex; justify-content: space-between; border-bottom: 1px solid var(--line); padding-bottom: 4px; }
.arith-item span:first-child { color: var(--muted); }
.arith-item span:last-child { font-weight: 600; font-variant-numeric: tabular-nums; }

/* Method View */
.method-view { display: flex; flex-direction: column; gap: 20px; }
.weakness-box {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px 20px;
  line-height: 1.6;
  color: var(--muted);
}
.weakness-box p { margin: 0 0 10px; }
.weakness-box p:last-child { margin-bottom: 0; }
.weakness-box strong { color: var(--ink); }
```

